do $$begin begin update public.tenant_users set role='viewer' where tenant_id=pg_temp.id(11) and user_id=pg_temp.id(1);perform pg_temp.write(pg_temp.request(62,'approve',(select (v->>'eventId')::uuid from custody_saved where kind='request')),2);raise exception 'retired customer owner request accepted';exception when insufficient_privilege then null;end;end$$;
