select pg_temp.refused(pg_temp.request(63,'activate',(select (v->>'eventId')::uuid from custody_saved where kind='approve')),2);
do $$begin begin update public.users set is_axiom_internal=false where id=pg_temp.id(2);perform pg_temp.write(pg_temp.request(63,'activate',(select (v->>'eventId')::uuid from custody_saved where kind='approve')),3);raise exception 'retired founder approval accepted';exception when insufficient_privilege then null;end;end$$;
insert into custody_saved select 'activate',pg_temp.write(pg_temp.request(63,'activate',(v->>'eventId')::uuid),3),pg_temp.request(63,'activate',(v->>'eventId')::uuid) from custody_saved where kind='approve';
set constraints all immediate;set constraints all deferred;
